def clock(h,m):
    import math
    a=lambda v,l: (16+l*math.sin(math.radians(v)), 16-l*math.cos(math.radians(v)))
    hx,hy=a(h*30+m*.5,5.5); mx,my=a(m*6,8.5)
    return f'<circle cx="16" cy="16" r="13" fill="#fff"/><path d="M16 16L{hx:.1f} {hy:.1f}" stroke-width="2.6"/><path d="M16 16L{mx:.1f} {my:.1f}"/><circle cx="16" cy="16" r="1.5" class="l"/>'
F['clock1']=clock(1,0); F['clock3']=clock(3,0)
